// Browser-level responsive regression test without a Playwright/Puppeteer dependency.
// Chrome DevTools Protocol tests the CSS generated by the actual Next.js build.
import assert from "node:assert/strict";
import { spawn, spawnSync } from "node:child_process";
import { mkdtempSync, mkdirSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { setTimeout as sleep } from "node:timers/promises";

const CHROME = ["google-chrome", "chromium", "chromium-browser"].find(
    (cmd) => spawnSync("which", [cmd], { stdio: "ignore" }).status === 0,
);
if (!CHROME) throw new Error("Headless Chrome is required for responsive layout checks");

const testWidths = [360, 768, 820, 1024, 1280];
const profile = mkdtempSync(join(tmpdir(), "serpente-browser-"));
const port = 9337;
const server = spawn(process.execPath, ["node_modules/next/dist/bin/next", "start", "-p", "3001"], {
    stdio: "ignore",
});
const browser = spawn(CHROME, [
    "--headless=new", "--no-sandbox", "--disable-dev-shm-usage",
    "--disable-gpu", "--remote-allow-origins=*",
    `--remote-debugging-port=${port}`, `--user-data-dir=${profile}`, "about:blank",
], { stdio: "ignore" });

async function until(fn, label, timeout = 30000) {
    const started = Date.now();
    while (Date.now() - started < timeout) {
        try { const result = await fn(); if (result) return result; } catch { /* wait */ }
        await sleep(250);
    }
    throw new Error(`Timed out waiting for ${label}`);
}

async function connectDebugger(wsUrl) {
    const ws = new WebSocket(wsUrl);
    let counter = 0;
    const pending = new Map();
    await new Promise((resolve, reject) => {
        ws.addEventListener("open", resolve, { once: true });
        ws.addEventListener("error", reject, { once: true });
    });
    ws.addEventListener("message", ({ data }) => {
        const response = JSON.parse(data);
        if (!response.id) return;
        const request = pending.get(response.id);
        if (!request) return;
        pending.delete(response.id);
        if (response.error) request.reject(new Error(JSON.stringify(response.error)));
        else request.resolve(response.result);
    });
    return {
        send(method, params = {}, sessionId) {
            return new Promise((resolve, reject) => {
                const id = ++counter;
                pending.set(id, { resolve, reject });
                ws.send(JSON.stringify({ id, method, params, sessionId }));
            });
        },
        close() { ws.close(); },
    };
}

const measure = `(() => {
    const shell = document.querySelector("main .site-shell");
    if (!shell) throw new Error("Site shell missing");
    const container = document.createElement("div");
    container.dataset.responsiveQa = "true";
    container.style.marginBlock = "1rem";
    shell.appendChild(container);

    // Sample content reproduces long tablet card titles, without relying
    // on production API data or authentication.
    const cards = document.createElement("div");
    cards.className = "fluid-card-grid";
    for (const label of [
        "Bảo hành 5 ngày",
        "Theo dõi @serpente.nailroom",
        "Thật sự là một trải nghiệm tuyệt vời",
    ]) {
        const article = document.createElement("article");
        article.className = "min-w-0 rounded-[22px] border border-line bg-surface p-[clamp(1rem,2.4vw,1.75rem)]";
        const title = document.createElement("h3");
        title.className = "fluid-card-title mt-4 font-serif";
        title.textContent = label;
        article.appendChild(title);
        cards.appendChild(article);
    }
    container.appendChild(cards);

    // Use the same intrinsic grid as the appointment date picker.
    const calendar = document.createElement("div");
    calendar.className = "mt-6 grid min-w-0 grid-cols-[repeat(auto-fit,minmax(min(100%,4.25rem),1fr))] gap-2";
    for (let i = 0; i < 14; i++) {
        const button = document.createElement("button");
        button.textContent = String(i + 1);
        button.className = "rounded-[12px] border px-2 py-3";
        calendar.appendChild(button);
    }
    container.appendChild(calendar);

    const shellBox = shell.getBoundingClientRect();
    const cardRects = [...cards.children].map((node) => node.getBoundingClientRect());
    const dateRects = [...calendar.children].map((node) => node.getBoundingClientRect());
    const rows = [...new Set(cardRects.map((rect) => Math.round(rect.top)))];
    const pageWidth = document.documentElement.scrollWidth;
    const viewportWidth = window.innerWidth;
    const within = (rect) => rect.left >= shellBox.left - 2 && rect.right <= shellBox.right + 2;
    return JSON.stringify({
        pageWidth, viewportWidth, shellWidth: shellBox.width,
        cardColumns: cardRects.filter((rect) => Math.round(rect.top) === rows[0]).length,
        cardsWithin: cardRects.every(within),
        datesWithin: dateRects.every(within),
        smallestDate: Math.min(...dateRects.map((rect) => rect.width)),
        calendarColumns: dateRects.filter((rect) => Math.round(rect.top) === Math.round(dateRects[0].top)).length,
        gridDisplay: getComputedStyle(cards).display,
    });
})()`;

let debuggerClient;
try {
    await until(async () => (await fetch("http://127.0.0.1:3001/services")).ok, "Next.js server");
    const version = await until(async () =>
        (await fetch(`http://127.0.0.1:${port}/json/version`)).json(), "Chrome debugger");
    debuggerClient = await connectDebugger(version.webSocketDebuggerUrl);
    const { targetId } = await debuggerClient.send("Target.createTarget", { url: "about:blank" });
    const { sessionId } = await debuggerClient.send("Target.attachToTarget", { targetId, flatten: true });
    await debuggerClient.send("Page.enable", {}, sessionId);
    const artifactDirectory = join(process.cwd(), "responsive-artifacts");
    mkdirSync(artifactDirectory, { recursive: true });

    for (const width of testWidths) {
        await debuggerClient.send("Emulation.setDeviceMetricsOverride", {
            width, height: 1000, deviceScaleFactor: 1, mobile: true,
        }, sessionId);
        await debuggerClient.send("Page.navigate", { url: "http://127.0.0.1:3001/services" }, sessionId);
        await until(async () => {
            const response = await debuggerClient.send("Runtime.evaluate", {
                expression: 'document.readyState === "complete" && !!document.querySelector("main .site-shell")',
                returnByValue: true,
            }, sessionId);
            return response.result?.value;
        }, `services at ${width}px`);
        const result = await debuggerClient.send("Runtime.evaluate", {
            expression: measure, returnByValue: true,
        }, sessionId);
        if (result.exceptionDetails) throw new Error(JSON.stringify(result.exceptionDetails));
        const metrics = JSON.parse(result.result.value);
        assert.equal(metrics.viewportWidth, width);
        assert.ok(metrics.pageWidth <= width + 2, `${width}px: horizontal page overflow ${metrics.pageWidth}`);
        assert.ok(metrics.cardsWithin, `${width}px: card overflow`);
        assert.ok(metrics.datesWithin, `${width}px: date control overflow`);
        assert.ok(metrics.smallestDate >= 60, `${width}px: date cell is too narrow`);
        assert.equal(metrics.gridDisplay, "grid");
        if (width <= 390) assert.equal(metrics.cardColumns, 1);
        if (width >= 768 && width <= 1024) assert.equal(metrics.cardColumns, 2);
        if (width >= 1280) assert.equal(metrics.cardColumns, 3);
        const image = await debuggerClient.send("Page.captureScreenshot", { format: "png", captureBeyondViewport: false }, sessionId);
        writeFileSync(join(artifactDirectory, `services-${width}px.png`), Buffer.from(image.data, "base64"));
        console.log(`PASS ${width}px`, metrics);
    }
} finally {
    debuggerClient?.close();
    browser.kill("SIGTERM");
    server.kill("SIGTERM");
    // Chrome can still be writing the profile after SIGTERM. Let the
    // ephemeral CI runner clean it up; never mask a layout assertion error.
}
